output-exprs.el:
comment:/*current in draft comment*/
  index(
    ac!allComments,
    wherecontains(
      true,
      ac!allComments.isDraft
    ),
    {}
  )

previousComments:/*All Previous Comments*/
  index(
    ac!allComments,
    wherecontains(
      false,
      ac!allComments.isDraft
    ),
    {}
  )
